static void ui_demo_update_function_visuals(void)
{
  uint32_t i;

  for (i = 0; i < UI_DEMO_FUNCTION_COUNT; i++)
    {
      const bool selected =
        g_ui.has_selection && g_ui.selected_function == i;
      lv_color_t fg = selected ? ui_demo_color(0x1f5eff) :
                                ui_demo_color(0x323842);

      if (g_ui.function_buttons[i] != NULL)
        {
          if (selected)
            {
              lv_obj_add_state(g_ui.function_buttons[i], LV_STATE_CHECKED);
            }
          else
            {
              lv_obj_remove_state(g_ui.function_buttons[i], LV_STATE_CHECKED);
            }
        }

      if (g_ui.function_items[i] != NULL)
        {
          lv_obj_set_style_radius(g_ui.function_items[i], 14, 0);
          lv_obj_set_style_bg_color(g_ui.function_items[i],
                                    selected ? ui_demo_color(0xdde8ff) :
                                               ui_demo_color(0xf8f9fb), 0);
          lv_obj_set_style_bg_opa(g_ui.function_items[i],
                                  selected ? LV_OPA_COVER : LV_OPA_TRANSP,
                                  0);
          lv_obj_set_style_border_width(g_ui.function_items[i],
                                        selected ? 2 : 0, 0);
          lv_obj_set_style_border_color(g_ui.function_items[i],
                                        ui_demo_color(0x1f5eff), 0);
        }

      if (g_ui.function_icons[i] != NULL)
        {
          lv_obj_set_style_text_color(g_ui.function_icons[i], fg, 0);
        }

      if (g_ui.function_labels[i] != NULL)
        {
          lv_obj_set_style_text_color(g_ui.function_labels[i], fg, 0);
        }
    }
}

