static bool lvgl_app_wait_path(const char *path, uint32_t timeout_ms)
{
  uint32_t waited_ms = 0;

  if (path == NULL || path[0] == '\0')
    {
      return false;
    }

  while (access(path, F_OK) < 0)
    {
      if (waited_ms >= timeout_ms)
        {
          return false;
        }

      usleep(50u * 1000u);
      waited_ms += 50u;
    }

  return true;
}

